use std::borrow::Cow;
use std::cell::RefCell;
use std::fmt;
use std::io;
use std::path::Path;
use std::time;

use termcolor::{ColorSpec, WriteColor};

pub(crate) use crate::color::ColorSpecs;

use bstr::{ByteSlice, ByteVec};
use grep_matcher::{Captures, LineTerminator, Match, Matcher};
use grep_searcher::{
    LineIter, Searcher, SinkContext, SinkContextKind, SinkError, SinkMatch,
};
#[cfg(feature = "serde1")]
use serde::{Serialize, Serializer};

use crate::MAX_LOOK_AHEAD;

/// A type for handling replacements while amortizing allocation.
pub struct Replacer<M: Matcher> {
    space: Option<Space<M>>,
    scratch: RefCell<Vec<u8>>,
    recorded_matches: Vec<Match>,
    colors: ColorSpecs,
}

struct Space<M: Matcher> {
    /// The place to store capture locations.
    caps: M::Captures,
    /// The place to write a replacement to.
    dst: Vec<u8>,
    /// The place to store match offsets in terms of `dst`.
    matches: Vec<Match>,
}

impl<M: Matcher> fmt::Debug for Replacer<M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (dst, matches) = self.replacement().unwrap_or((&[], &[]));
        f.debug_struct("Replacer")
            .field("dst", &dst)
            .field("matches", &matches)
            .finish()
    }
}

impl<M: Matcher> Replacer<M> {
    /// Create a new replacer for use with a particular matcher.
    ///
    /// This constructor does not allocate. Instead, space for dealing with
    /// replacements is allocated lazily only when needed.
    pub fn new() -> Replacer<M> {
        Replacer {
            space: None,
            scratch: RefCell::new(vec![]),
            recorded_matches: vec![],
            colors: ColorSpecs::default(),
        }
    }

    /// Executes a replacement on the given subject string by replacing all
    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
    ///
    /// This can fail if the underlying matcher reports an error.
    pub fn replace_all<'a>(
        &'a mut self,
        searcher: &Searcher,
        matcher: &M,
        mut subject: &[u8],
        range: std::ops::Range<usize>,
        replacement: &[u8],
    ) -> io::Result<()> {
        // See the giant comment in 'find_iter_at_in_context' below for why we
        // do this dance.
        let is_multi_line = searcher.multi_line_with_matcher(&matcher);
        if is_multi_line {
            if subject[range.end..].len() >= MAX_LOOK_AHEAD {
                subject = &subject[..range.end + MAX_LOOK_AHEAD];
            }
        } else {
            // When searching a single line, we should remove the line
            // terminator. Otherwise, it's possible for the regex (via
            // look-around) to observe the line terminator and not match
            // because of it.
            let mut m = Match::new(0, range.end);
            trim_line_terminator(searcher, subject, &mut m);
            subject = &subject[..m.end()];
        }
        {
            let &mut Space { ref mut dst, ref mut caps, ref mut matches } =
                self.allocate(matcher)?;
            dst.clear();
            matches.clear();

            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
        }
        Ok(())
    }

    /// Return the result of the prior replacement and the match offsets for
    /// all replacement occurrences within the returned replacement buffer.
    ///
    /// If no replacement has occurred then `None` is returned.
    pub fn replacement<'a>(&'a self) -> Option<(&'a [u8], &'a [Match])> {
        match self.space {
            None => None,
            Some(ref space) => {
                if space.matches.is_empty() {
                    None
                } else {
                    Some((&space.dst, &space.matches))
                }
            }
        }
    }

    /// Clear space used for performing a replacement.
    ///
    /// Subsequent calls to `replacement` after calling `clear` (but before
    /// executing another replacement) will always return `None`.
    pub fn clear(&mut self) {
        if let Some(ref mut space) = self.space {
            space.dst.clear();
            space.matches.clear();
        }
    }

    /// Allocate space for replacements when used with the given matcher and
    /// return a mutable reference to that space.
    ///
    /// This can fail if allocating space for capture locations from the given
    /// matcher fails.
    fn allocate(&mut self, matcher: &M) -> io::Result<&mut Space<M>> {
        if self.space.is_none() {
            let caps =
                matcher.new_captures().map_err(io::Error::error_message)?;
            self.space =
                Some(Space { caps: caps, dst: vec![], matches: vec![] });
        }
        Ok(self.space.as_mut().unwrap())
    }
}


impl<M: Matcher> Replacer<M> {
    pub(crate) fn install_color_specs(&mut self, specs: &ColorSpecs) {
        self.colors = specs.clone();
    }

    pub(crate) fn color_path(&self) -> &ColorSpec {
        self.colors.path()
    }

    pub(crate) fn color_line(&self) -> &ColorSpec {
        self.colors.line()
    }

    pub(crate) fn color_column(&self) -> &ColorSpec {
        self.colors.column()
    }

    pub(crate) fn color_matched(&self) -> &ColorSpec {
        self.colors.matched()
    }

    pub(crate) fn clear_recorded_matches(&mut self) {
        self.recorded_matches.clear();
    }

    pub(crate) fn recorded_matches(&self) -> &[Match] {
        &self.recorded_matches
    }

    pub(crate) fn recorded_match_count(&self) -> u64 {
        self.recorded_matches.len() as u64
    }

    pub(crate) fn push_recorded_match(&mut self, m: Match) {
        if m.start() > m.end() {
            return;
        }
        if let Some(last) = self.recorded_matches.last() {
            if last.end() > m.start() && last.start() <= m.start() {
                return;
            }
        }
        self.recorded_matches.push(m);
    }

    pub(crate) fn pop_trailing_empty_recorded(&mut self, range_end: usize) {
        if self.recorded_matches.is_empty() {
            return;
        }
        let last = *self.recorded_matches.last().unwrap();
        if last.is_empty() && last.start() >= range_end {
            self.recorded_matches.pop();
        }
    }

    pub(crate) fn record_matches_in_context<N, F>(
        &mut self,
        searcher: &Searcher,
        matcher: N,
        bytes: &[u8],
        range: std::ops::Range<usize>,
        mut on_match: F,
    ) -> io::Result<()>
    where
        N: Matcher,
        F: FnMut(Match) -> bool,
    {
        self.recorded_matches.clear();
        let start = range.start;
        find_iter_at_in_context(searcher, matcher, bytes, range.clone(), |m| {
            let rel = Match::new(m.start() - start, m.end() - start);
            self.recorded_matches.push(rel);
            on_match(rel)
        })?;
        self.pop_trailing_empty_recorded(range.end.saturating_sub(range.start));
        Ok(())
    }

    pub(crate) fn scratch_bytes(&self) -> std::cell::Ref<[u8]> {
        std::cell::Ref::map(self.scratch.borrow(), |v| v.as_slice())
    }

    pub(crate) fn clear_scratch(&self) {
        self.scratch.borrow_mut().clear();
    }

    pub(crate) fn format_decimal_into_scratch(&self, n: u64) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        Self::push_decimal(&mut buf, n);
    }

    pub(crate) fn format_padded_decimal_into_scratch(&self, n: u64, width: usize) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        let mut tmp = [0u8; 20];
        let mut x = n;
        let mut len = 0usize;
        if x == 0 {
            tmp[0] = b'0';
            len = 1;
        } else {
            while x > 0 {
                tmp[len] = b'0' + (x % 10) as u8;
                x /= 10;
                len += 1;
            }
        }
        if width > len {
            for _ in 0..(width - len) {
                buf.push(b'0');
            }
        }
        while len > 0 {
            len -= 1;
            buf.push(tmp[len]);
        }
    }

    pub(crate) fn format_hex_into_scratch(&self, n: u64, prefixed: bool) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        if prefixed {
            buf.extend_from_slice(b"0x");
        }
        let mut tmp = [0u8; 16];
        let mut x = n;
        let mut len = 0usize;
        if x == 0 {
            buf.push(b'0');
            return;
        }
        while x > 0 {
            let d = (x & 0xF) as u8;
            tmp[len] = if d < 10 { b'0' + d } else { b'a' + (d - 10) };
            x >>= 4;
            len += 1;
        }
        while len > 0 {
            len -= 1;
            buf.push(tmp[len]);
        }
    }

    pub(crate) fn format_quoted_bytes_into_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.push(b'"');
        Self::push_escaped_bytes(&mut buf, bytes);
        buf.push(b'"');
    }

    pub(crate) fn format_json_string_into_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.push(b'"');
        Self::push_json_escaped(&mut buf, bytes);
        buf.push(b'"');
    }

    pub(crate) fn format_json_bytes_into_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.extend_from_slice(b"{\"bytes\":\"");
        Self::push_base64(&mut buf, bytes);
        buf.extend_from_slice(b"\"}");
    }

    pub(crate) fn format_base64_into_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        Self::push_base64(&mut buf, bytes);
    }

    pub(crate) fn format_path_display_into_scratch(&self, path: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        if path.is_empty() {
            buf.extend_from_slice(b"<stdin>");
            return;
        }
        for (i, &b) in path.iter().enumerate() {
            if b == b'\\' || b == b'/' {
                buf.push(b'/');
                continue;
            }
            if b >= 0x20 && b <= 0x7E && b != b'"' {
                buf.push(b);
                continue;
            }
            if i + 1 < path.len() && Self::is_utf8_cont(path[i + 1]) && b >= 0xC2 {
                buf.push(b);
                continue;
            }
            buf.push(b);
        }
    }

    pub(crate) fn format_duration_into_scratch(&self, duration: time::Duration) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        let secs = duration.as_secs();
        let nanos = duration.subsec_nanos();
        Self::push_decimal(&mut buf, secs);
        buf.push(b'.');
        let mut frac = nanos / 1000;
        let mut tmp = [0u8; 6];
        for i in 0..6 {
            tmp[5 - i] = b'0' + (frac % 10) as u8;
            frac /= 10;
        }
        buf.extend_from_slice(&tmp);
        buf.push(b's');
    }

    pub(crate) fn format_match_span_into_scratch(&self, m: Match) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.push(b'[');
        Self::push_decimal(&mut buf, m.start() as u64);
        buf.push(b',');
        Self::push_decimal(&mut buf, m.end() as u64);
        buf.push(b']');
    }

    pub(crate) fn format_binary_message_into_scratch(
        &self,
        warning: bool,
        byte: u8,
        offset: u64,
    ) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        if warning {
            buf.extend_from_slice(
                b"WARNING: stopped searching binary file after match (found ",
            );
        } else {
            buf.extend_from_slice(b"binary file matches (found ");
        }
        Self::push_byte_debug(&mut buf, byte);
        buf.extend_from_slice(b" byte around offset ");
        Self::push_decimal(&mut buf, offset);
        buf.extend_from_slice(b")\n");
    }

    pub(crate) fn format_omitted_into_scratch(
        &self,
        kind: u8,
        match_count: usize,
        remaining: usize,
    ) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        if kind == 0 {
            buf.extend_from_slice(b"[... omitted end of long line]");
        } else if kind == 1 {
            buf.extend_from_slice(b" [... ");
            Self::push_decimal(&mut buf, remaining as u64);
            if remaining == 1 {
                buf.extend_from_slice(b" more match]");
            } else {
                buf.extend_from_slice(b" more matches]");
            }
        } else if kind == 2 {
            buf.extend_from_slice(b"[Omitted long context line]");
        } else if kind == 3 {
            buf.extend_from_slice(b"[Omitted long matching line]");
        } else {
            buf.extend_from_slice(b"[Omitted long line with ");
            Self::push_decimal(&mut buf, match_count as u64);
            buf.extend_from_slice(b" matches]");
        }
    }

    pub(crate) fn copy_trimmed_to_scratch(
        &self,
        bytes: &[u8],
        range: Match,
        line_term: LineTerminator,
    ) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        let trimmed = trim_ascii_prefix(line_term, bytes, range);
        if trimmed.start() < trimmed.end() && trimmed.end() <= bytes.len() {
            buf.extend_from_slice(&bytes[trimmed]);
        }
    }

    pub(crate) fn copy_match_window_to_scratch(&self, bytes: &[u8], m: Match) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        let start = if m.start() > bytes.len() { bytes.len() } else { m.start() };
        let end = if m.end() > bytes.len() { bytes.len() } else { m.end() };
        if start < end {
            buf.extend_from_slice(&bytes[start..end]);
        }
    }

    pub(crate) fn escape_bytes_to_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        Self::push_escaped_bytes(&mut buf, bytes);
    }

    pub(crate) fn format_separator_into_scratch(&self, sep: &[u8], add_term: Option<u8>) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.extend_from_slice(sep);
        if let Some(term) = add_term {
            buf.push(term);
        }
    }

    pub(crate) fn format_count_with_label_into_scratch(&self, n: u64, label: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.extend_from_slice(label);
        Self::push_decimal(&mut buf, n);
    }

    pub(crate) fn decode_lossy_to_scratch(&self, bytes: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        let mut i = 0;
        while i < bytes.len() {
            let adv = Self::utf8_advance(bytes, i);
            if adv == 0 {
                buf.extend_from_slice(b"\xEF\xBF\xBD");
                i += 1;
            } else {
                buf.extend_from_slice(&bytes[i..i + adv]);
                i += adv;
            }
        }
    }

    pub(crate) fn format_range_list_into_scratch(&self, matches: &[Match]) {
        let mut buf = self.scratch.borrow_mut();
        buf.clear();
        buf.push(b'[');
        for (i, m) in matches.iter().enumerate() {
            if i > 0 {
                buf.push(b',');
            }
            Self::push_decimal(&mut buf, m.start() as u64);
            buf.push(b'-');
            Self::push_decimal(&mut buf, m.end() as u64);
        }
        buf.push(b']');
    }

    pub(crate) fn truncate_scratch_to_max_columns(&self, max_columns: Option<u64>) {
        let mut buf = self.scratch.borrow_mut();
        if let Some(maxc) = max_columns {
            if maxc == 0 {
                buf.clear();
                return;
            }
            if buf.len() as u64 > maxc {
                let keep = maxc as usize;
                let mut end = 0;
                let mut seen = 0usize;
                while end < buf.len() && seen < keep {
                    let adv = Self::utf8_advance(&buf, end);
                    if adv == 0 {
                        end += 1;
                    } else {
                        end += adv;
                    }
                    seen += 1;
                }
                buf.truncate(end);
            }
        }
    }

    pub(crate) fn append_line_term_to_scratch(&self, term: &[u8]) {
        let mut buf = self.scratch.borrow_mut();
        if term.is_empty() {
            buf.push(b'\n');
        } else {
            buf.extend_from_slice(term);
        }
    }

    pub(crate) fn write_scratch_all<W: io::Write>(&self, wtr: &mut W) -> io::Result<()> {
        wtr.write_all(&self.scratch.borrow())
    }

    pub(crate) fn write_colored_scratch<W: WriteColor>(
        &self,
        wtr: &mut W,
        spec: &ColorSpec,
    ) -> io::Result<()> {
        if spec.is_none() {
            return wtr.write_all(&self.scratch.borrow());
        }
        wtr.set_color(spec)?;
        wtr.write_all(&self.scratch.borrow())?;
        wtr.reset()
    }

    pub(crate) fn relative_match_offsets(&self, m: Match, range_start: usize) -> Match {
        let start = if m.start() < range_start { 0 } else { m.start() - range_start };
        let end = if m.end() < range_start { 0 } else { m.end() - range_start };
        if start <= end {
            Match::new(start, end)
        } else {
            Match::new(end, start)
        }
    }

    pub(crate) fn should_quit_search(
        &self,
        match_count: u64,
        max_matches: Option<u64>,
        after_context_remaining: u64,
    ) -> bool {
        {
            let mut buf = self.scratch.borrow_mut();
            buf.clear();
            Self::push_decimal(&mut buf, match_count);
            buf.push(b'/');
            Self::push_decimal(&mut buf, max_matches.unwrap_or(0));
            buf.push(b'/');
            Self::push_decimal(&mut buf, after_context_remaining);
        }
        let limit = match max_matches {
            None => return false,
            Some(limit) => limit,
        };
        if match_count < limit {
            return false;
        }
        after_context_remaining == 0
    }

    pub(crate) fn match_more_than_limit(
        &self,
        match_count: u64,
        max_matches: Option<u64>,
    ) -> bool {
        {
            let mut buf = self.scratch.borrow_mut();
            buf.clear();
            Self::push_decimal(&mut buf, match_count);
            buf.push(b':');
            Self::push_decimal(&mut buf, max_matches.unwrap_or(0));
        }
        match max_matches {
            None => false,
            Some(limit) => match_count > limit,
        }
    }

    pub(crate) fn choose_field_separator<'a>(
        &self,
        is_context: bool,
        context_sep: &'a [u8],
        match_sep: &'a [u8],
    ) -> &'a [u8] {
        if is_context {
            context_sep
        } else {
            match_sep
        }
    }

    pub(crate) fn needs_match_granularity(
        &self,
        supports_color: bool,
        match_colored: bool,
        column: bool,
        has_replacement: bool,
        per_match: bool,
        only_matching: bool,
        stats: bool,
    ) -> bool {
        (supports_color && match_colored)
            || column
            || has_replacement
            || per_match
            || only_matching
            || stats
    }

    pub(crate) fn exceeds_column_limit(&self, line_len: u64, max_columns: Option<u64>) -> bool {
        match max_columns {
            None => false,
            Some(limit) => line_len > limit,
        }
    }

    pub(crate) fn clip_match_to_line(&self, line: Match, m: Match) -> Option<Match> {
        if m.end() <= line.start() {
            return None;
        }
        if m.start() >= line.end() {
            return None;
        }
        let start = if m.start() < line.start() { line.start() } else { m.start() };
        let end = if m.end() > line.end() { line.end() } else { m.end() };
        if start < end {
            Some(Match::new(start, end))
        } else {
            None
        }
    }

    pub(crate) fn count_remaining_preview_matches(
        &self,
        matches: &[Match],
        line_end: usize,
        original_end: usize,
    ) -> usize {
        let mut n = 0usize;
        for m in matches {
            if m.start() >= line_end && m.start() < original_end {
                n += 1;
            }
        }
        n
    }

    pub(crate) fn grapheme_preview_end(
        &self,
        bytes: &[u8],
        line: Match,
        max_columns: u64,
    ) -> usize {
        if max_columns == 0 {
            return line.start();
        }
        let slice = if line.end() <= bytes.len() { &bytes[line] } else { &bytes[line.start().min(bytes.len())..] };
        let mut end = 0usize;
        let mut seen = 0u64;
        while end < slice.len() && seen < max_columns {
            let adv = Self::utf8_advance(slice, end);
            if adv == 0 {
                end += 1;
            } else {
                end += adv;
            }
            seen += 1;
        }
        line.start() + end
    }

    pub(crate) fn json_use_pretty(&self, pretty: bool) -> bool {
        pretty
    }

    pub(crate) fn summary_should_show_count(&self, exclude_zero: bool, match_count: u64) -> bool {
        !exclude_zero || match_count > 0
    }

    pub(crate) fn summary_kind_tag(&self, kind_path_with: bool, kind_path_without: bool, has_match: bool) -> u8 {
        if kind_path_with {
            if has_match { 1 } else { 0 }
        } else if kind_path_without {
            if has_match { 0 } else { 1 }
        } else if has_match {
            2
        } else {
            3
        }
    }

    pub(crate) fn classify_line_terminator(&self, buf: &[u8]) -> u8 {
        if buf.ends_with(b"\r\n") {
            2
        } else if buf.ends_with(b"\n") {
            1
        } else if buf.ends_with(b"\r") {
            3
        } else {
            0
        }
    }

    pub(crate) fn is_space_byte(&self, b: u8, line_term: LineTerminator) -> bool {
        if line_term.as_bytes().contains(&b) {
            return false;
        }
        match b {
            b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r' | b' ' => true,
            _ => false,
        }
    }

    pub(crate) fn next_line_bounds(&self, bytes: &[u8], start: usize, term: u8) -> Match {
        if start >= bytes.len() {
            return Match::new(bytes.len(), bytes.len());
        }
        let mut i = start;
        while i < bytes.len() {
            if bytes[i] == term {
                return Match::new(start, i + 1);
            }
            if term == b'\n' && bytes[i] == b'\r' {
                if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                    return Match::new(start, i + 2);
                }
            }
            i += 1;
        }
        Match::new(start, bytes.len())
    }

    pub(crate) fn count_lines_in(&self, bytes: &[u8], term: u8) -> u64 {
        if bytes.is_empty() {
            return 0;
        }
        let mut n = 1u64;
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == term {
                if i + 1 < bytes.len() {
                    n += 1;
                }
            }
            i += 1;
        }
        n
    }

    pub(crate) fn match_covers_newline(&self, bytes: &[u8], m: Match) -> bool {
        if m.start() >= m.end() || m.end() > bytes.len() {
            return false;
        }
        for &b in &bytes[m] {
            if b == b'\n' || b == b'\r' {
                return true;
            }
        }
        false
    }

    pub(crate) fn sink_strategy(
        &self,
        has_matches: bool,
        multi_line: bool,
        is_context: bool,
    ) -> u8 {
        if !has_matches {
            if multi_line && !is_context {
                1
            } else {
                0
            }
        } else if multi_line && !is_context {
            3
        } else {
            2
        }
    }

    pub(crate) fn after_context_step(
        &self,
        over_limit: bool,
        remaining: u64,
        searcher_after: u64,
    ) -> u64 {
        if over_limit {
            remaining.saturating_sub(1)
        } else {
            searcher_after
        }
    }

    pub(crate) fn binary_should_stop(
        &self,
        convert: bool,
        already_found: bool,
    ) -> bool {
        convert && already_found
    }

    pub(crate) fn heading_should_print_path(
        &self,
        heading: bool,
        this_search_written: bool,
    ) -> bool {
        heading && !this_search_written
    }

    pub(crate) fn search_separator_needed(
        &self,
        sep_present: bool,
        this_search_written: bool,
        ever_written: bool,
    ) -> bool {
        sep_present && !this_search_written && ever_written
    }

    pub(crate) fn path_terminator_or<'a>(
        &self,
        path_term: Option<u8>,
        fallback: &'a [u8],
    ) -> [u8; 1] {
        match path_term {
            Some(b) => [b],
            None => {
                if fallback.is_empty() {
                    [b'\n']
                } else {
                    [fallback[0]]
                }
            }
        }
    }

    pub(crate) fn utf8_text_or_bytes<'a>(&self, bytes: &'a [u8]) -> Result<&'a str, &'a [u8]> {
        match std::str::from_utf8(bytes) {
            Ok(s) => Ok(s),
            Err(_) => Err(bytes),
        }
    }

    pub(crate) fn invert_should_record(&self, invert: bool) -> bool {
        invert
    }

    pub(crate) fn begin_should_continue(&self, max_matches: Option<u64>) -> bool {
        max_matches != Some(0)
    }

    pub(crate) fn finish_should_suppress_binary(
        &self,
        binary_offset: Option<u64>,
        quit_byte: Option<u8>,
    ) -> bool {
        binary_offset.is_some() && quit_byte.is_some()
    }

    pub(crate) fn only_matching_slice<'a>(&self, bytes: &'a [u8], m: Match) -> &'a [u8] {
        if m.end() <= bytes.len() && m.start() <= m.end() {
            &bytes[m]
        } else {
            &[]
        }
    }

    pub(crate) fn per_match_line_number(
        &self,
        base: Option<u64>,
        bytes: &[u8],
        m: Match,
        term: u8,
    ) -> Option<u64> {
        let base = match base {
            None => return None,
            Some(n) => n,
        };
        if m.start() > bytes.len() {
            return Some(base);
        }
        let mut extra = 0u64;
        for &b in &bytes[..m.start()] {
            if b == term {
                extra += 1;
            }
        }
        Some(base + extra)
    }

    pub(crate) fn column_from_match(&self, m: Match) -> u64 {
        (m.start() as u64).saturating_add(1)
    }

    pub(crate) fn absolute_from_match(&self, base: u64, m: Match) -> u64 {
        base.saturating_add(m.start() as u64)
    }

    pub(crate) fn replacement_available(&self) -> bool {
        match self.replacement() {
            None => false,
            Some((bytes, matches)) => !bytes.is_empty() || !matches.is_empty(),
        }
    }

    pub(crate) fn replacement_match_count(&self) -> usize {
        match self.replacement() {
            None => 0,
            Some((_, matches)) => matches.len(),
        }
    }

    pub(crate) fn replacement_byte_len(&self) -> usize {
        match self.replacement() {
            None => 0,
