        }
    }

    pub(crate) fn replacement_span(&self) -> Option<Match> {
        match self.replacement() {
            None => None,
            Some((_, matches)) => {
                if matches.is_empty() {
                    None
                } else {
                    let start = matches[0].start();
                    let end = matches[matches.len() - 1].end();
                    Some(Match::new(start, end))
                }
            }
        }
    }

    pub(crate) fn space_allocated(&self) -> bool {
