    }

    fn push_decimal(buf: &mut Vec<u8>, mut n: u64) {
        let mut tmp = [0u8; 20];
        let mut len = 0usize;
        if n == 0 {
            buf.push(b'0');
            return;
        }
        while n > 0 {
            tmp[len] = b'0' + (n % 10) as u8;
            n /= 10;
            len += 1;
        }
        while len > 0 {
            len -= 1;
            buf.push(tmp[len]);
        }
    }

    fn push_byte_debug(buf: &mut Vec<u8>, b: u8) {
        if b >= 0x20 && b <= 0x7E && b != b'\\' {
            buf.push(b);
            return;
        }
        buf.push(b'\\');
        match b {
            b'\n' => buf.push(b'n'),
            b'\r' => buf.push(b'r'),
            b'\t' => buf.push(b't'),
            b'\\' => buf.push(b'\\'),
            _ => {
                buf.push(b'x');
                let hi = b >> 4;
                let lo = b & 0xF;
                buf.push(if hi < 10 { b'0' + hi } else { b'a' + (hi - 10) });
                buf.push(if lo < 10 { b'0' + lo } else { b'a' + (lo - 10) });
            }
        }
    }

    fn push_escaped_bytes(buf: &mut Vec<u8>, bytes: &[u8]) {
        for &b in bytes {
            match b {
                b'\\' => buf.extend_from_slice(b"\\\\"),
                b'"' => buf.extend_from_slice(b"\\\""),
                b'\n' => buf.extend_from_slice(b"\\n"),
                b'\r' => buf.extend_from_slice(b"\\r"),
                b'\t' => buf.extend_from_slice(b"\\t"),
                0x00..=0x1F | 0x7F => {
                    buf.extend_from_slice(b"\\x");
                    let hi = b >> 4;
                    let lo = b & 0xF;
                    buf.push(if hi < 10 { b'0' + hi } else { b'a' + (hi - 10) });
                    buf.push(if lo < 10 { b'0' + lo } else { b'a' + (lo - 10) });
                }
                _ => buf.push(b),
            }
        }
    }

    fn push_json_escaped(buf: &mut Vec<u8>, bytes: &[u8]) {
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            match b {
                b'"' => buf.extend_from_slice(b"\\\""),
                b'\\' => buf.extend_from_slice(b"\\\\"),
                b'\n' => buf.extend_from_slice(b"\\n"),
                b'\r' => buf.extend_from_slice(b"\\r"),
                b'\t' => buf.extend_from_slice(b"\\t"),
                0x08 => buf.extend_from_slice(b"\\b"),
                0x0C => buf.extend_from_slice(b"\\f"),
                0x00..=0x1F => {
                    buf.extend_from_slice(b"\\u00");
                    let hi = b >> 4;
                    let lo = b & 0xF;
                    buf.push(if hi < 10 { b'0' + hi } else { b'a' + (hi - 10) });
                    buf.push(if lo < 10 { b'0' + lo } else { b'a' + (lo - 10) });
                }
                0x20..=0x7F => buf.push(b),
                _ => {
                    let adv = Self::utf8_advance(bytes, i);
                    if adv == 0 {
                        buf.extend_from_slice(b"\\uFFFD");
                        i += 1;
                        continue;
                    } else {
                        buf.extend_from_slice(&bytes[i..i + adv]);
                        i += adv;
                        continue;
                    }
                }
            }
            i += 1;
        }
    }

    fn push_base64(buf: &mut Vec<u8>, bytes: &[u8]) {
        const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut i = 0;
        while i < bytes.len() {
            let b0 = bytes[i];
            let b1 = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };
            let b2 = if i + 2 < bytes.len() { bytes[i + 2] } else { 0 };
            buf.push(TABLE[(b0 >> 2) as usize]);
            buf.push(TABLE[(((b0 & 0x03) << 4) | (b1 >> 4)) as usize]);
            if i + 1 < bytes.len() {
                buf.push(TABLE[(((b1 & 0x0F) << 2) | (b2 >> 6)) as usize]);
            } else {
                buf.push(b'=');
            }
            if i + 2 < bytes.len() {
                buf.push(TABLE[(b2 & 0x3F) as usize]);
            } else {
                buf.push(b'=');
            }
            i += 3;
        }
    }

    fn is_utf8_cont(b: u8) -> bool {
        b & 0xC0 == 0x80
    }

    fn utf8_advance(bytes: &[u8], i: usize) -> usize {
        if i >= bytes.len() {
            return 0;
        }
        let b = bytes[i];
        let lead = Self::UTF8_LEAD_LEN[b as usize] as usize;
        if lead <= 1 {
            return lead;
        }
        if i + lead > bytes.len() {
            return 0;
        }
        if lead == 2 {
            if !Self::is_utf8_cont(bytes[i + 1]) {
                return 0;
            }
            return 2;
        }
        if lead == 3 {
            if !Self::is_utf8_cont(bytes[i + 1]) || !Self::is_utf8_cont(bytes[i + 2]) {
                return 0;
            }
            if b == 0xE0 && bytes[i + 1] < 0xA0 {
                return 0;
            }
            if b == 0xED && bytes[i + 1] >= 0xA0 {
                return 0;
            }
            return 3;
        }
        if !Self::is_utf8_cont(bytes[i + 1])
            || !Self::is_utf8_cont(bytes[i + 2])
            || !Self::is_utf8_cont(bytes[i + 3])
        {
            return 0;
        }
        if b == 0xF0 && bytes[i + 1] < 0x90 {
            return 0;
        }
        if b == 0xF4 && bytes[i + 1] >= 0x90 {
            return 0;
        }
        4
    }
}

